PRAGMA foreign_keys=OFF;
PRAGMA user_version=5;
BEGIN TRANSACTION;
CREATE TABLE entries (
    seq INTEGER PRIMARY KEY,
    at_ms INTEGER NOT NULL,
    kind TEXT NOT NULL CHECK(kind IN ('campaign', 'candidate', 'verdict', 'call', 'tool-call', 'call-result', 'tool-result')),
    body TEXT NOT NULL CHECK(json_valid(body) AND json_type(body) = 'object'),
    material BLOB CHECK((kind = 'candidate') = (material IS NOT NULL))
  ) STRICT;
INSERT INTO entries VALUES(1,1787664646444,'campaign','{"application":"elenx-solve","config":{"protocol":"exploration-v13","problem":"Prove that for every integer n, the product n(n+1) is even.\n","completionCriteria":"Give a standalone proof covering every integer n. The exported answer must contain the parity argument rather than refer to campaign memory.\n","memory":"claims-and-routes","maxContextTokens":100000,"guidance":{"explorer":[{"origin":"default","text":"Guidance is strategy advice, not mathematical evidence, and cannot change the goal, completion criteria, or audit requirements."},{"origin":"default","text":"State every conditional result as an exact implication with its hypotheses."},{"origin":"user","text":"When no live claims are visible, prove and nominate the parity classification completely: apply Euclidean division by 2, write n=2q+r with integers q,r and 0<=r<2, deduce r is 0 or 1, and prove the alternatives are exclusive. Record the parity-case route and leave claimsComplete false. When live claims are visible, cite the needed claim and finish the exact goal."}],"coordinator":[{"origin":"default","text":"Guidance is strategy advice, not mathematical evidence, and cannot change the goal, completion criteria, or audit requirements."},{"origin":"default","text":"Represent a conditional mathematical result as an exact implication whose statement includes every hypothesis."},{"origin":"user","text":"Retain the packet-supported parity claim and parity-case route. A route may reference the new claim created earlier in the same batch."}]},"coordinator":{"provider":"openai-codex","model":"gpt-5.6-luna","reasoning":"low","api":"openai-codex-responses","baseUrl":"https://chatgpt.com/backend-api"},"explorer":{"provider":"openai-codex","model":"gpt-5.6-luna","reasoning":"low","api":"openai-codex-responses","baseUrl":"https://chatgpt.com/backend-api"},"admissionAuditors":[{"provider":"openai-codex","model":"gpt-5.6-luna","reasoning":"low","name":"claim-route-audit","api":"openai-codex-responses","baseUrl":"https://chatgpt.com/backend-api"}],"resolutionAuditors":[{"provider":"openai-codex","model":"gpt-5.6-luna","reasoning":"low","kind":"premise-audit","api":"openai-codex-responses","baseUrl":"https://chatgpt.com/backend-api"},{"provider":"openai-codex","model":"gpt-5.6-luna","reasoning":"low","kind":"proof-audit","api":"openai-codex-responses","baseUrl":"https://chatgpt.com/backend-api"},{"provider":"openai-codex","model":"gpt-5.6-luna","reasoning":"low","kind":"reconstruction","api":"openai-codex-responses","baseUrl":"https://chatgpt.com/backend-api"}]}}',NULL);
CREATE TRIGGER entries_no_update BEFORE UPDATE ON entries BEGIN SELECT RAISE(ABORT, 'entries are append-only'); END;
CREATE TRIGGER entries_no_delete BEFORE DELETE ON entries BEGIN SELECT RAISE(ABORT, 'entries are append-only'); END;
CREATE UNIQUE INDEX one_campaign ON entries(kind) WHERE kind = 'campaign';
CREATE UNIQUE INDEX one_result ON entries(json_extract(body, '$.parent')) WHERE kind IN ('call-result', 'tool-result');
CREATE UNIQUE INDEX one_verdict_call ON entries(json_extract(body, '$.call')) WHERE kind = 'verdict';
COMMIT;
